import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Swap a live session for a fresh one for the same user; undefined if the token isn't live. */
export function refreshSession(token: string): Session | undefined {
  const session = getSession(token);
  if (!session) return undefined;
  revokeSession(token);
  return createSession(session.userId);
}

